insert into public.stores (id, name, slug, tagline, story, region, plan) values
  ('a1000000-0000-4000-8000-000000000001', 'Mama Nkechi''s Kitchen', 'mama-nkechis-kitchen', 'Home-style West African cooking, shipped worldwide', 'Three generations of family recipes from Enugu, cooked in small batches and sealed fresh the day they are made.', 'Lagos, Nigeria', 'heritage'),
  ('a1000000-0000-4000-8000-000000000002', 'Cape Bakehouse', 'cape-bakehouse', 'Heritage breads and sweet traditions from the Cape', 'A family bakery in the Bo-Kaap keeping Cape Malay baking alive, from Vetkoek to Malva pudding.', 'Cape Town, South Africa', 'starter'),
  ('a1000000-0000-4000-8000-000000000003', 'Roots & Remedies', 'roots-and-remedies', 'Traditional herbal wisdom, respectfully prepared', 'Sustainably wild-harvested roots, barks and teas prepared by a third-generation herbalist.', 'Harare, Zimbabwe', 'starter'),
  ('a1000000-0000-4000-8000-000000000004', 'Kalahari Creations', 'kalahari-creations', 'Art and adornment from the desert heartland', 'A collective of San and Nama artists producing carvings, beadwork and textiles that tell the story of the Kalahari.', 'Ghanzi, Botswana', 'heritage');
insert into public.products (id, store_id, title, slug, category, description, price_cents, currency, image_url, stock, is_published) values
  ('b1000000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000001', 'Smoked Jollof Spice Blend', 'smoked-jollof-spice-blend', 'foods', 'Our signature smoky party-rice blend: sun-dried peppers, smoked paprika, curry leaf and a whisper of fermented locust bean. Makes 8 generous pots.', 899, 'USD', 'https://images.unsplash.com/photo-1596040033229-a9821ebd058d?w=800&q=80', 120, true),
  ('b1000000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000001', 'Egusi Seeds, Whole', 'egusi-seeds-whole', 'foods', 'Hand-shelled melon seeds for the classic groundnut-thickened soup. Earthy, rich and protein-packed.', 1249, 'USD', 'https://images.unsplash.com/photo-1599599810769-bcde5a160d32?w=800&q=80', 80, true),
  ('b1000000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000001', 'Suya Pepper Rub', 'suya-pepper-rub', 'foods', 'Street-corner suya flavour at home: roasted groundnut, ginger, cayenne and our secret spice mix. Excellent on beef, chicken or mushrooms.', 749, 'USD', 'https://images.unsplash.com/photo-1596496181848-3091d4878b24?w=800&q=80', 150, true),
  ('b1000000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000001', 'Dried Iru (Locust Beans)', 'dried-iru-locust-beans', 'foods', 'Naturally fermented locust beans, the savoury backbone of ewedu and egusi stews. Packed in resealable pouches.', 649, 'USD', 'https://images.unsplash.com/photo-1615485500704-8e990f9900f7?w=800&q=80', 60, true),
  ('b1000000-0000-4000-8000-000000000005', 'a1000000-0000-4000-8000-000000000002', 'Rooibos & Honey Rusks', 'rooibos-honey-rusks', 'baking', 'Twice-baked Cape rusks infused with rooibos and raw Karoo honey. Made for dunking into morning coffee.', 1099, 'USD', 'https://images.unsplash.com/photo-1509440159596-0249088772ff?w=800&q=80', 90, true),
  ('b1000000-0000-4000-8000-000000000006', 'a1000000-0000-4000-8000-000000000002', 'Malva Pudding Kit', 'malva-pudding-kit', 'baking', 'Everything you need for the sticky caramel Cape classic: pre-measured dry mix, apricot jam and the family sauce recipe card.', 1599, 'USD', 'https://images.unsplash.com/photo-1486427944299-d1955d23e34d?w=800&q=80', 45, true),
  ('b1000000-0000-4000-8000-000000000007', 'a1000000-0000-4000-8000-000000000002', 'Bo-Kaap Koeksister Box', 'bo-kaap-koeksister-box', 'baking', 'Six syrup-drenched twisted doughnuts, fried to order and glazed in cardamom syrup. Ships chilled.', 1899, 'USD', 'https://images.unsplash.com/photo-1519676867240-f03562e64548?w=800&q=80', 30, true),
  ('b1000000-0000-4000-8000-000000000008', 'a1000000-0000-4000-8000-000000000002', 'Stone-Ground Maize Meal, 5kg', 'stone-ground-maize-meal-5kg', 'baking', 'Coarse, fragrant maize meal milled the slow way — perfect pap, phutu or mielie bread.', 1299, 'USD', 'https://images.unsplash.com/photo-1610478920397-e5d3f3b32d72?w=800&q=80', 100, true),
  ('b1000000-0000-4000-8000-000000000009', 'a1000000-0000-4000-8000-000000000003', 'Devil''s Claw Root, Cut', 'devils-claw-root-cut', 'medicinals', 'Traditionally used for joint comfort and mobility. Sustainably harvested in the Kalahari and shade-dried whole.', 1699, 'USD', 'https://images.unsplash.com/photo-1509824227185-9c5a01ceba0d?w=800&q=80', 70, true),
  ('b1000000-0000-4000-8000-000000000010', 'a1000000-0000-4000-8000-000000000003', 'Baobab Fruit Powder', 'baobab-fruit-powder', 'medicinals', 'Sun-dried baobab pulp, naturally high in vitamin C and fibre. Stir into porridge, smoothies or water.', 1399, 'USD', 'https://images.unsplash.com/photo-1610970881699-44a5587cabec?w=800&q=80', 110, true),
  ('b1000000-0000-4000-8000-000000000011', 'a1000000-0000-4000-8000-000000000003', 'Moringa Leaf Tea', 'moringa-leaf-tea', 'medicinals', 'Hand-picked moringa leaves, gently dried to keep the green. A daily tonic tea with a soft, grassy sweetness.', 899, 'USD', 'https://images.unsplash.com/photo-1519676867240-f03562e64548?w=800&q=80', 130, true),
  ('b1000000-0000-4000-8000-000000000012', 'a1000000-0000-4000-8000-000000000003', 'African Potato Balm', 'african-potato-balm', 'medicinals', 'A soothing topical balm of African potato root, shea and beeswax, blended by our herbalist for aching muscles and dry skin.', 1249, 'USD', 'https://images.unsplash.com/photo-1587854692152-cbe660dbde88?w=800&q=80', 55, true),
  ('b1000000-0000-4000-8000-000000000013', 'a1000000-0000-4000-8000-000000000004', 'Hand-Carved Walking Stick', 'hand-carved-walking-stick', 'art', 'One-piece leadwood walking stick, carved with a kudu head by master carver Xukuri. Each piece is signed and unique.', 8900, 'USD', 'https://images.unsplash.com/photo-1513519245088-0e12902e5a38?w=800&q=80', 8, true),
  ('b1000000-0000-4000-8000-000000000014', 'a1000000-0000-4000-8000-000000000004', 'Ostrich Eggshell Necklace', 'ostrich-eggshell-necklace', 'art', 'Traditional San beadwork: hundreds of hand-cracked, drilled and polished ostrich eggshell beads on a leather cord.', 4500, 'USD', 'https://images.unsplash.com/photo-1535632066927-ab7c9ab60908?w=800&q=80', 12, true),
  ('b1000000-0000-4000-8000-000000000015', 'a1000000-0000-4000-8000-000000000004', 'Kalahari Sunset Tapestry', 'kalahari-sunset-tapestry', 'art', 'Hand-woven wall hanging in dyed wool, capturing the last light over the red dunes. Roughly 120 x 80 cm.', 12500, 'USD', 'https://images.unsplash.com/photo-1528459801416-a9e53bbf4e17?w=800&q=80', 5, true),
  ('b1000000-0000-4000-8000-000000000016', 'a1000000-0000-4000-8000-000000000004', 'Telling Tales Print Set', 'telling-tales-print-set', 'art', 'Set of three archival prints of San rock-art inspired drawings by artist /Ui, printed on cotton rag paper.', 3200, 'USD', 'https://images.unsplash.com/photo-1578321272176-b7bbc0679853?w=800&q=80', 20, true);